import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"5、【需】 乾下坎上","description":"周易口诀义 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"周易口诀义 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/007.md","filePath":"zh/classics/koujueyi/007.md"}'),r={name:"zh/classics/koujueyi/007.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>彖曰：需，须也，险在前也。刚健而不陷，其义不困穷矣。「需，有孚，光亨，贞吉」，位乎天位，以正中也。「利涉大川」，往有功也。</p><p>象曰：云上于天，需。君子以饮食宴乐。</p><p>初九：需于郊，利用恒，无咎。</p><p>象曰：「需于郊」，不犯难行也。「利用恒无咎」，未失常也。</p><p>九二，需于沙，小有言，终吉。</p><p>象曰：「需于沙」，衍在中也。虽小有言，以吉终也。</p><p>九三，雷于泥，致寇至。象曰：「需于泥」，灾在外也。自我致寇，敬慎不败也。</p><p>六四，需于血，出自穴。</p><p>象曰：「需于血」，顺以听也。</p><p>九五，需于酒食，贞吉。</p><p>象曰：酒食贞吉，以中正也。</p><p>上六，入于穴，有不速之客三人来，敬之终吉。</p><p>象曰：「不速之客来，敬之终吉」，虽不当位，未大失也。</p><p>解读</p><p>「需有孚光亨贞吉」者，需，待也，乾健获进，坎险在前，畏而不进，故称待也。凡人待物，必须有信，信既立矣，即道德亨通，于正获吉，故曰「光亨贞吉」也。「利涉大川」者，以信待物，又以「乾」之刚健，不患于险，故可济涉大川，不忧沉溺也。</p><p>象曰「云上于天，需，君子以饮食宴乐」者，「坎」为云也，乾，天也，云上于天，待时降雨，是需待之象也。君子当其时，待养而成，故王氏云：「童蒙已发，盛德光亨，饮食宴乐，其在兹乎！」</p><p>「初九，需于郊，利用恒，无咎」者，尔雅云：「邑外谓之郊也。」初九去难既远，虽不应于几速，但可以处于郊境之外，待时而已也。「利用恒，无咎」者，既不逼于险难，其所营为不失恒道，故不陷于咎也。</p><p>「九二，需于沙，小有言，终吉」，「沙」谓水之旁，去难渐近。既近于难，不能不有责让之言。以其刚健，宽而处中，待时而进，虽有责让之言，终保吉矣，故曰：「小有言，终吉」也。</p><p>「九三，需于泥，致寇至」者，九三已逼于难，故称「泥」，「泥」谓险难也。「致寇至」者，招也。既逼险难，即是招致寇害，以相侵敌，然而不为遽进，犹有待焉，故不为困惫。</p><p>「六四，需于血，出自穴」者，血是阴阳相伤也。六四以阴柔之质，当刚健之路，乾刚既进，必见侵伤，故曰「需于血」。阳既强盛而前进，力不能敌，故以出于窟穴而避之，故曰「出自穴」也。</p><p>九五，需于酒食，贞吉者，人之所须，以求贵位，身既处于尊位而为天下所归，即何更望求焉？但施酒食，畅其中情而已，故曰「需于酒食」也。然至饮食过节，患所生焉，故纣作靡靡之乐，天下为之离叛，必须饮食以宜，而不失贞正之道，可以获吉，故曰「贞吉」也。</p><p>「上六：入于穴，有不速之客三人来，敬之，终吉」者，上六需难既终，不须出穴，安于旧位，故曰「入于穴」也。速，召也。三人，谓乾三阳也。言难道既终，三阳务进，不待上六召唤而自来矣，故曰「有不速之客三人来」也。阳贵阴贱，而上六既是阴柔，又居无位之地，三阳若来，必须恭敬之而终获吉，故曰「敬之，终吉」。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
